    title: "Bulls vs Lakers and the NBA Playoffs",
    year: 1992,
    genre: "Esporte",
    console: "Mega Drive",
    curiosities: [
      "Bulls vs Lakers and the NBA Playoffs é um jogo de basquete desenvolvido pela Electronic Arts e lançado em 1992 exclusivamente para o Sega Mega Drive. O jogo é a sequência de Lakers vs Celtics. O nome do jogo faz referência à série final da NBA da temporada anterior, a final de 1991 entre o Chicago Bulls e o Los Angeles Lakers. É o segundo jogo da série NBA Playoffs. Embora não haja uma versão para SNES de Bulls vs Lakers, a versão para SNES (e primeira versão) de Bulls vs Blazers foi fortemente baseada em Bulls vs Lakers, com a versão posterior para Mega Drive introduzindo algumas mudanças. Bulls vs Lakers introduziu uma apresentação no estilo de transmissão televisiva com uma rede de televisão fictícia, 'EASN', a Electronic Arts Sports Network. Foi o primeiro jogo de basquete em equipe a apresentar um recurso de replay instantâneo durante a partida. Bing Gordon, o Diretor de Criação da Electronic Arts, foi o narrador do jogo. Este também foi o primeiro jogo a exibir os logotipos dos times da NBA nas quadras.",
    ],
