    curiosities: [
      "Lemmings 2: The Tribes é um jogo de estratégia e quebra -cabeça de 1993 , desenvolvido pela DMA Design e publicado pela Psygnosis , sendo a sequência do jogo Lemmings de 1991. Similar ao título original, o jogador controla lemingues antropomorfizados através de diversos níveis, utilizando várias habilidades para alcançar a saída. Expandindo a mecânica do jogo original, Lemmings 2 introduziu uma narrativa abrangente e apresentou uma série de níveis mais abertos, baseados em diferentes 'tribos' de lemingues, além de aumentar o número de habilidades disponíveis e simplificar os requisitos para completar os níveis. O desenvolvimento de Lemmings 2 foi mais intenso, com a Psygnosis tendo maior envolvimento na tentativa de recriar o sucesso do jogo original. Um dos focos da produção foi o desenvolvimento de diversas versões para diferentes consoles, incluindo Mega Drive , Super NES e Game Boy . Lemmings 2 foi um sucesso comercial e recebeu críticas positivas, com elogios direcionados às suas mecânicas de jogo adicionais e à maior variedade de níveis e habilidades.",
    ],
