      "O mundo alienígena de Mer está sendo devorado por uma substância maligna conhecida como Água Negra. Somente Ren, um jovem príncipe, pode impedi-la encontrando os Treze Tesouros Perdidos da Regra. Sua leal tripulação de desajustados que o ajudam em sua jornada é composta pela ecomante Tula, o pirata Ioz, ávido por tesouros, e o macaco-pássaro Niddler. O maligno lorde pirata Bloth não medirá esforços para obter os tesouros para si e criará muitos obstáculos para Ren e sua tripulação. O jogo para Mega Drive é a única obra da franquia Piratas das Águas Negras que oferece um desfecho para a história, já que a série de televisão na qual se baseia foi cancelada antes que todos os treze tesouros fossem coletados e as Águas Negras destruídas.",
