      "O jogo é dividido em duas partes. A primeira se passa em uma rua (provavelmente a Rua Evergreen Terrace , mas chamada de Windy World). Bart caminha e precisa encontrar cinco páginas de sua lição de casa enquanto evita inimigos como caixas de correio vivas e vários personagens do desenho. Os itens que Bart pode coletar incluem chiclete (com o qual ele pode soprar bolhas para repelir inimigos ou coletar Zs azuis flutuantes para restaurar sua saúde), sementes de melancia (que ele pode cuspir nos inimigos para derrotá-los ou fazê-los mudar de direção), travesseiros (que criam uma nova barra de saúde se ele ficar sem Zs) e seu skate (que aumenta temporariamente sua velocidade, além de restaurar e estender sua barra de saúde quanto mais tempo ele o usa). Jimbo e sua turma vão forçar Bart a passear com eles, fazendo com que Bart perca o controle de seus movimentos e tenha que se mover junto com eles, sofrendo dano no processo. Acertar um saxofone voador invocará Lisa Simpson com asas de fada para jogar pó mágico em Jimbo e sua turma e transformá-los em ratos, libertando Bart. No entanto, se Bart estiver sozinho, a fada Lisa o transformará em um sapo que não pode atacar. Se Bart pegar um beijo soprado por uma senhora idosa, ele voltará à sua forma humana .",
