      "Um protótipo do jogo foi extraído pela SegaAge em novembro de 2010. [3] Ele descreve o jogo como um sidescroller onde você controla o Monstro do Pântano atacando inimigos. Você também tem a habilidade de se transformar em objetos próximos, como troncos. Infelizmente, há apenas uma música usada em todo o jogo e, devido aos controles rígidos, o jogo é muito difícil. Devido a um erro na extração, os dados do jogo foram duplicados oito vezes. A análise dos dados da sobreposição mostra que as cópias não apresentam diferenças, sendo todas idênticas. A extração da SegaAge não foi feita corretamente, mas uma versão refinada da ROM está disponível ao lado da sobreposição original. Devido à falta de uma nova extração, o protótipo de Monstro do Pântano não está presente na maioria dos bancos de dados de ROMs.",
